def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate, lb, ub):
        return np.clip(candidate, lb, ub)

    best_candidate = lb + (ub - lb) * rng.rand(dim)
    best_fitness = func(best_candidate)

    temperature = 1.0
    cooling_rate = 0.99

    for _ in range(budget):
        candidate = clip(best_candidate + rng.randn(dim), lb, ub)

        # Differential Evolution step
        mutation = 0.5 * (rng.rand(dim) - 0.5) / np.sqrt(_ + 1) 
        candidate += mutation * (candidate - best_candidate)

        fitness = func(candidate)

        # Simulated Annealing step
        if fitness < best_fitness:
            best_candidate = candidate
            best_fitness = fitness

        temperature *= cooling_rate

        # Accept worse solutions with probability exp(-(fitness - best_fitness) / temperature)
        if rng.rand() < np.exp(-(fitness - best_fitness) / temperature):
            best_candidate = candidate
            best_fitness = fitness

    return clip(best_candidate, lb, ub)

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        return func(x)

    pop_size = int(1e3)
    population = rng.uniform(lb, ub, (pop_size, dim))
    velocity = 0.5 * rng.uniform(-1, 1, (pop_size, dim))

    for _ in range(budget - 1):
        fitness = np.array([evaluate(x) for x in population])
        indices = np.argsort(fitness)[:int(0.2 * pop_size)]
        new_population = population[indices]
        velocity = 0.5 * rng.uniform(-1, 1, (pop_size, dim))

        for i in range(pop_size):
            if i not in indices:
                r1, r2, r3 = np.random.choice(indices, size=3, replace=False)
                v_i = velocity[i] + rng.uniform(-1, 1) * (
                    population[r1] - population[r2]
                ) + 0.5 * (population[r3] - population[r1])
                new_population[i] += v_i
                if np.any(new_population[i] < lb) or np.any(new_population[i] > ub):
                    new_population[i] = np.clip(
                        new_population[i], lb, ub
                    )

        population = new_population.copy()
        velocity = 0.5 * rng.uniform(-1, 1, (pop_size, dim))

    best_individual = population[np.argmin(fitness)]
    return best_individual

